{"command":"cd /work/workspace/deliverable && python3 - <<'EOF'
import json
data = json.load(open('achados.json'))
print("itens:", len(data))
allowed = {"anuencia","preco","indenizacao","prazo","nenhum"}
keys = {"achado","onde","por_que_importa","solucao","efeito"}
bad = []
for i, item in enumerate(data, 1):
    missing = keys - set(item)
    extra = set(item) - keys
    eff = item.get("efeito")
    if missing or extra or eff not in allowed:
        bad.append((i, missing, extra, eff))
    if not all(isinstance(item.get(k), str) and item.get(k).strip() for k in keys):
        bad.append((i, "empty-field"))
print("problemas:", bad if bad else "nenhum")
from collections import Counter
print(Counter(i["efeito"] for i in data))
EOF"}
